@dataclass(frozen=True)
class FunctionArgumentSource:
    """Actual argument nodes and kinds, independent of default alignment."""

    argument: ast.arg
    kind: CompactParameterKind

    @classmethod
    def from_arguments(cls, arguments: ast.arguments) -> tuple[Self, ...]:
        parameters = [
            cls(argument, CompactParameterKind.POSITIONAL_ONLY)
            for argument in arguments.posonlyargs
        ]
        parameters.extend(cls(argument, CompactParameterKind.POSITIONAL_OR_KEYWORD)
                          for argument in arguments.args)
        if arguments.vararg is not None:
            parameters.append(cls(arguments.vararg, CompactParameterKind.VAR_POSITIONAL))
        parameters.extend(cls(argument, CompactParameterKind.KEYWORD_ONLY)
                          for argument in arguments.kwonlyargs)
        if arguments.kwarg is not None:
            parameters.append(cls(arguments.kwarg, CompactParameterKind.VAR_KEYWORD))
        return tuple(parameters)

    @staticmethod
    def annotation_roots(parameters: Iterable[FunctionArgumentSource], returns: ast.expr | None) -> tuple[ast.expr, ...]:
        """Project expressions, preserving the supplied argument-root order."""
        return tuple(parameter.argument.annotation for parameter in parameters
                     if parameter.argument.annotation is not None) + (() if returns is None else (returns,))

